changeSet.sql:
CREATE TABLE type_poste ( id_type_poste SERIAL, nom_type_poste VARCHAR(50) NOT NULL, rang_type_poste INTEGER NOT NULL, PRIMARY KEY (id_type_poste) );
CREATE TABLE poste ( id_poste SERIAL, nom_poste VARCHAR(50) NOT NULL, description_poste VARCHAR(255) NOT NULL, id_type_poste INTEGER NOT NULL, PRIMARY KEY (id_poste), FOREIGN KEY (id_type_poste) REFERENCES type_poste (id_type_poste) );
CREATE TABLE type_contrat ( id_type_contrat SERIAL, type_contrat VARCHAR(50), PRIMARY KEY (id_type_contrat) );
CREATE TABLE contrat ( id_contrat SERIAL, contrat VARCHAR(100) NOT NULL, date_debut DATE NOT NULL, date_fin DATE, salaire_horaire NUMERIC(15, 2) NOT NULL, nb_jour_semaine INTEGER NOT NULL, nb_heure_jour NUMERIC(15, 2) NOT NULL, id_poste INTEGER NOT NULL, id_talent INTEGER NOT NULL, id_type_contrat INTEGER NOT NULL, PRIMARY KEY (id_contrat), FOREIGN KEY (id_poste) REFERENCES poste (id_poste), FOREIGN KEY (id_talent) REFERENCES talent (id_talent), FOREIGN KEY (id_type_contrat) REFERENCES type_contrat (id_type_contrat) );
CREATE TABLE absence ( id_absence SERIAL, motif VARCHAR(50), date_absence DATE NOT NULL, id_contrat INTEGER NOT NULL, PRIMARY KEY (id_absence), FOREIGN KEY (id_contrat) REFERENCES contrat (id_contrat) );
CREATE TABLE heure_supplementaire ( id SERIAL, motif TEXT, date_heure_debut TIMESTAMP NOT NULL, date_heure_creation TIMESTAMP NOT NULL DEFAULT NOW(), nb_heure NUMERIC(5, 2) NOT NULL, taux_majoration NUMERIC(5, 2) NOT NULL, id_contrat INTEGER NOT NULL, PRIMARY KEY (id), FOREIGN KEY (id_contrat) REFERENCES contrat (id_contrat) );
CREATE TABLE type_rupture ( id_type_rupture SERIAL, nom_type_rupture VARCHAR(50) NOT NULL, PRIMARY KEY (id_type_rupture), UNIQUE (nom_type_rupture) );
CREATE TABLE rupture ( id_rupture SERIAL, date_rupture DATE NOT NULL, date_rupture_validation DATE, motif VARCHAR(50), id_type_rupture INTEGER NOT NULL, id_contrat INTEGER NOT NULL, PRIMARY KEY (id_rupture), UNIQUE (id_contrat), FOREIGN KEY (id_type_rupture) REFERENCES type_rupture (id_type_rupture), FOREIGN KEY (id_contrat) REFERENCES contrat (id_contrat) );
